INSERT INTO questions (question_type, question_text, options, answer, explanation, difficulty, topic, company_tag, role_tag, language, active) VALUES
('CODING','Write a C# LINQ query to group a list of orders by customer and return the total order value per customer.','',NULL,'orders.GroupBy(o => o.CustomerId).Select(g => new { CustomerId = g.Key, Total = g.Sum(o => o.Value) })','Medium','LINQ',NULL,'dotnet','C#',true),
('CODING','Implement IDisposable correctly on a class that wraps an unmanaged resource.','',NULL,'Implement Dispose() to release the resource, call GC.SuppressFinalize(this), and follow the standard dispose pattern with a protected virtual Dispose(bool disposing) overload.','Medium','Memory Management',NULL,'dotnet','C#',true),
('CODING','Write an async method that calls two independent APIs concurrently and combines their results.','',NULL,'var t1 = client.GetAsync(url1); var t2 = client.GetAsync(url2); await Task.WhenAll(t1, t2); then combine t1.Result and t2.Result.','Medium','Async',NULL,'dotnet','C#',true),
('CODING','Write a middleware component in ASP.NET Core that logs the request path and response status code.','',NULL,'Create a class with an InvokeAsync(HttpContext) method that logs context.Request.Path before calling _next(context), then logs context.Response.StatusCode after.','Medium','ASP.NET Core',NULL,'dotnet','C#',true),
('CODING','Write an Entity Framework Core query that eagerly loads a related collection to avoid N+1 queries.','',NULL,'dbContext.Orders.Include(o => o.OrderItems).ToList() — Include() eagerly loads OrderItems in the same query instead of one query per Order.','Medium','Entity Framework',NULL,'dotnet','C#',true),
('CODING','Implement a generic repository interface and a concrete implementation using EF Core.','',NULL,'Define IRepository<T> with Add/Get/Update/Delete methods, then implement it with a DbContext-backed class using DbSet<T> generically.','Medium','Design Patterns',NULL,'dotnet','C#',true),
('CODING','Write a unit test using xUnit and Moq for a service method that depends on an injected repository interface.','',NULL,'var mockRepo = new Mock<IRepository>(); mockRepo.Setup(r => r.GetById(1)).Returns(new Item()); var service = new Service(mockRepo.Object); Assert on service behavior.','Easy','Testing',NULL,'dotnet','C#',true),
('CODING','Fix a deadlock caused by calling .Result on an async method inside an ASP.NET controller action.','',NULL,'Change the controller action to async Task<IActionResult> and use await instead of .Result, avoiding blocking on the synchronization context.','Hard','Async',NULL,'dotnet','C#',true),
INSERT INTO questions (question_type, question_text, options, answer, explanation, difficulty, topic, company_tag, role_tag, language, active) VALUES
('SYSTEM_DESIGN','Design a multi-tenant SaaS backend using ASP.NET Core and a shared database.','',NULL,'Cover tenant isolation strategy (shared schema with a TenantId column vs schema-per-tenant) and how middleware resolves the current tenant per request.','Medium','System Design',NULL,'dotnet',NULL,true),
('SYSTEM_DESIGN','Design a background job processing system in .NET for sending bulk emails.','',NULL,'Cover a queue (Azure Service Bus/RabbitMQ), a hosted worker service consuming it, and retry/dead-letter handling for failed sends.','Medium','System Design',NULL,'dotnet',NULL,true),
('SYSTEM_DESIGN','Design a caching layer for a high-traffic .NET Web API to reduce database load.','',NULL,'Cover cache-aside pattern with Redis, cache invalidation strategy, and handling cache stampede on a popular key expiring.','Medium','System Design',NULL,'dotnet',NULL,true),
('SYSTEM_DESIGN','Design an audit logging system that tracks every change made to sensitive records in a .NET application.','',NULL,'Cover intercepting changes via EF Core SaveChanges override or a dedicated audit table, and how to keep it from adding significant write latency.','Medium','System Design',NULL,'dotnet',NULL,true),
('SYSTEM_DESIGN','Design a rate-limited public API gateway for a .NET microservices backend.','',NULL,'Cover token bucket/sliding window algorithms, per-client vs per-IP limiting, and where enforcement lives (gateway vs each service).','Medium','System Design',NULL,'dotnet',NULL,true),
('SYSTEM_DESIGN','Design an offline-first note-taking mobile app that syncs across devices.','',NULL,'Cover local-first storage as source of truth, a sync engine with conflict resolution, and how sync status is surfaced to the user.','Medium','System Design',NULL,'mobile',NULL,true),
('SYSTEM_DESIGN','Design the architecture for a mobile app supporting both online and offline maps/navigation.','',NULL,'Cover pre-downloaded tile caching, background sync of map updates, and gracefully degrading features that need connectivity.','Medium','System Design',NULL,'mobile',NULL,true),
('SYSTEM_DESIGN','Design a push notification system for a mobile app with millions of users.','',NULL,'Cover fan-out via APNs/FCM, batching, and how to avoid notification storms/throttling from the platform providers.','Medium','System Design',NULL,'mobile',NULL,true),
('SYSTEM_DESIGN','Design an image-heavy social feed for mobile with smooth scrolling performance.','',NULL,'Cover image caching/downsampling, pagination, and view recycling to avoid memory pressure and jank.','Medium','System Design',NULL,'mobile',NULL,true),
('SYSTEM_DESIGN','Design an in-app A/B testing and feature flag system for a mobile app.','',NULL,'Cover remote config delivery, bucketing users deterministically, and rolling a flag back instantly without a new app release.','Medium','System Design',NULL,'mobile',NULL,true),
('SYSTEM_DESIGN','Design a Salesforce integration architecture connecting Salesforce to an external ERP system.','',NULL,'Cover choosing between real-time REST callouts vs batch middleware (MuleSoft), and how to handle data volume and error retries.','Medium','System Design',NULL,'salesforce',NULL,true),
('SYSTEM_DESIGN','Design a scalable Apex trigger architecture for an org with many objects and complex automation.','',NULL,'Cover a single trigger per object with a handler class pattern, and a framework for ordering/bypassing automation cleanly.','Medium','System Design',NULL,'salesforce',NULL,true),
('SYSTEM_DESIGN','Design a data archiving strategy for a Salesforce org approaching storage limits.','',NULL,'Cover identifying archivable objects, using Big Objects or external storage, and preserving reporting/compliance access to archived data.','Medium','System Design',NULL,'salesforce',NULL,true),
('SYSTEM_DESIGN','Design a Salesforce deployment pipeline (CI/CD) for a team of 10 developers working in parallel.','',NULL,'Cover source-driven development with scratch orgs, automated validation on PRs, and a promotion path through sandboxes to production.','Medium','System Design',NULL,'salesforce',NULL,true),
('SYSTEM_DESIGN','Design a real-time order status sync between Salesforce and an external fulfillment system.','',NULL,'Cover Platform Events or Change Data Capture for near real-time propagation, and idempotency for handling duplicate/out-of-order events.','Medium','System Design',NULL,'salesforce',NULL,true),
('SYSTEM_DESIGN','Design an S/4HANA migration approach for a company running a heavily customized legacy SAP ECC system.','',NULL,'Cover greenfield vs brownfield vs bluefield migration strategies and how to decide which fits based on customization level.','Medium','System Design',NULL,'sap',NULL,true),
('SYSTEM_DESIGN','Design an integration architecture connecting SAP with a non-SAP e-commerce platform for real-time inventory sync.','',NULL,'Cover middleware choice (SAP PI/PO or Integration Suite), message format standardization, and handling sync failures gracefully.','Medium','System Design',NULL,'sap',NULL,true),
('SYSTEM_DESIGN','Design a custom authorization concept for a new SAP module rollout across multiple business units.','',NULL,'Cover role design (single vs composite roles), segregation of duties analysis, and how roles map to organizational structure.','Medium','System Design',NULL,'sap',NULL,true),
('SYSTEM_DESIGN','Design a Fiori app architecture for field technicians that must work with unreliable connectivity.','',NULL,'Cover offline OData sync (SAP Offline Store), conflict resolution on reconnect, and minimizing payload size for slow networks.','Medium','System Design',NULL,'sap',NULL,true),
('SYSTEM_DESIGN','Design a data migration approach for cutting over master data from a legacy system into a new SAP implementation.','',NULL,'Cover data cleansing, staging/validation before load, mock cutover dry-runs, and a rollback plan if the go-live fails.','Medium','System Design',NULL,'sap',NULL,true),
('SYSTEM_DESIGN','Design a Security Operations Center (SOC) monitoring architecture for a mid-size company.','',NULL,'Cover log sources feeding a SIEM, alert correlation rules, tiered analyst escalation, and how alert fatigue is managed.','Medium','System Design',NULL,'cybersecurity',NULL,true),
('SYSTEM_DESIGN','Design an incident response process and supporting tooling for a ransomware attack scenario.','',NULL,'Cover detection, containment (network isolation), eradication, recovery from backups, and post-incident forensics/lessons learned.','Medium','System Design',NULL,'cybersecurity',NULL,true),
('SYSTEM_DESIGN','Design a Zero Trust network access architecture for a company transitioning from a traditional VPN.','',NULL,'Cover identity-based access per application, device posture checks, and micro-segmentation replacing broad network-level trust.','Medium','System Design',NULL,'cybersecurity',NULL,true),
('SYSTEM_DESIGN','Design a vulnerability management program for an organization with thousands of endpoints.','',NULL,'Cover scan cadence, risk-based prioritization (CVSS + asset criticality + exploitability), and SLA-driven remediation tracking.','Medium','System Design',NULL,'cybersecurity',NULL,true),
('SYSTEM_DESIGN','Design a secure CI/CD pipeline that prevents secrets and vulnerable dependencies from reaching production.','',NULL,'Cover secret scanning pre-commit/pre-merge, dependency/SCA scanning, and gating deploys on failed security checks.','Medium','System Design',NULL,'cybersecurity',NULL,true);
